-- Contenido editable de la landing (HU-32). No incluye imágenes.
-- Puede repetirse: conserva cualquier contenido editado anteriormente.
CREATE TABLE IF NOT EXISTS contenido_landing (
  id TINYINT UNSIGNED NOT NULL,
  contenido JSON NOT NULL,
  actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT chk_landing_unica CHECK (id = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO contenido_landing (id, contenido)
SELECT 1, '{"nombre_parroquia":"Parroquia San Pedro Nolasco","lema":"Casa de oración · Guatemala","titulo_principal":"Una comunidad que camina unida en la fe","descripcion_principal":"Somos una parroquia viva al servicio de las familias de nuestro barrio. Celebramos, acompañamos y servimos — con las puertas siempre abiertas para quien busca consuelo, formación o un lugar donde pertenecer.","quienes_somos":{"titulo":"Más de setenta años sirviendo a nuestra comunidad","descripcion":"La Parroquia San Pedro Nolasco nació del deseo de un pequeño grupo de familias por tener un lugar de encuentro con Dios. Hoy somos una comunidad numerosa que conserva ese mismo espíritu: cercanía, sencillez y servicio.","mision":"Anunciar el Evangelio y acompañar a las familias a ejemplo de San Pedro Nolasco e intercesión de la Santísima Virgen María de la Merced.","comunidad":"La parroquia cuenta con treinta y seis grupos, comunidades y pastorales.","servicio":"Vivencia de los Sacramentos, visitas a enfermos, apoyo a familias en necesidad y formación permanente en las comunidades."},"cantidad_grupos":36,"cantidad_espacios":10,"valores_encabezado":{"titulo":"Lo que sostiene nuestra vida parroquial","descripcion":"Estos principios guían todo lo que hacemos: desde la celebración dominical hasta el acompañamiento silencioso de una familia en duelo."},"valores":[{"titulo":"Fe viva","descripcion":"Celebramos los sacramentos con cuidado y reverencia, y cultivamos una oración que acompaña la vida real de cada familia."},{"titulo":"Servicio","descripcion":"\\"El Hijo del hombre no vino para ser servido, sino para servir\\" (Mateo 20:28). Nadie sirve solo. Ministros, coordinadores y voluntarios trabajan juntos para que cada necesidad encuentre una respuesta."},{"titulo":"Comunidad","descripcion":"Aquí nadie es un extraño. Creamos espacios donde jóvenes, adultos y mayores se encuentran y se acompañan."},{"titulo":"Formación","descripcion":"Catequesis para niños, preparación sacramental y círculos de estudio abiertos a quien desee profundizar su fe."},{"titulo":"Caridad","descripcion":"Acompañamos a las familias que atraviesan dificultades con apoyo concreto, discreto y sostenido en el tiempo."},{"titulo":"Tradición","descripcion":"Cuidamos las celebraciones y devociones que nos identifican, heredadas de quienes levantaron esta parroquia."},{"titulo":"Redención","descripcion":"Acompañando en las esclavitudes modernas.","imagen":"/uploads/landing/valor-redencion-v1.webp"},{"titulo":"Misión","descripcion":"IGNIS REDENTOR: junto a Cristo Redentor y nuestra Madre de la Merced, trabajamos en la redención de los cautivos.","imagen":"/uploads/landing/valor-mision-v1.webp"}],"horarios_misa":[{"dias":"Domingo","horas":["08:00","10:00","12:00","18:00"]},{"dias":"Lunes a viernes","horas":["07:00","18:00"]}],"horarios_oficina":[{"dias":"Lunes a viernes","horario":"09:00 a 12:00"},{"dias":"Sábados y Domingos","horario":"Cerrado"}],"contacto":{"titulo":"Estamos aquí para acompañarte","direccion":"9a Calle A 9-34, Ciudad San Cristóbal, Mixco","correo":"parroquiasanpedronolascocsc@gmail.com","telefono":"+502 2443 3174"},"texto_pie":"Una comunidad de fe al servicio de las familias de nuestro barrio.","devocion":{"titulo":"Devoción a Nuestra Santísima Madre de la Merced","descripcion":"Cómo honramos a la Madre de Dios y a los santos de la Orden.","oracion":{"titulo":"¡Quédate con nosotros, Señor!","texto":"Padre nuestro, te damos gracias por la casa en que vivimos. Te invocamos con ánimo agradecido para que derrames tu abundante bendición sobre nuestra familia. Necesitamos ese regalo generoso y te lo pedimos con fe sincera y la confianza de hijos. Te damos gracias de todo corazón por tu bondad paternal.\\n\\nAsístenos en todo momento, para que sintamos tu presencia protectora, no como huésped, sino como Padre amoroso que cuida de sus hijos. Ahuyenta todo mal de nuestros corazones y de esta casa.\\n\\nQue la sagrada Familia de Nazaret sea nuestro modelo de fe sencilla y de disponibilidad total a cumplir tu Voluntad.\\n\\nQue practiquemos las virtudes que nos infundiste en el Bautismo y seamos ejemplo de vida cristiana para cuantos se relacionen con nosotros.\\n\\nAyúdanos a sobrellevar con paciencia las pruebas en la enfermedad, en la vejez y en todas las contrariedades que se nos presenten.\\n\\nImploramos tu ayuda para realizar todo en el nombre del Padre, del Hijo y del Espíritu Santo.\\n\\nAmén."},"tarjetas":[{"titulo":"Conocer e imitar a María","descripcion":"Para conocerla mejor e imitarla, los mercedarios estudiamos con particular interés la figura de María; con sencillez y competencia debemos exponer su misión y privilegios, y con nuestra vida y ejemplo hemos de ser promotores de auténtico culto mariano.","imagen":"/uploads/landing/devocion-conocer-e-imitar-a-maria-v1.webp"},{"titulo":"Cómo honramos a la Madre de Dios","descripcion":"Honramos a la Madre de Dios en especial con los siguientes actos:\\n1° Rezo diario de una parte del rosario;\\n2° Los sábados, según las leyes litúrgicas, misa de nuestra santísima Madre, y liturgia de las horas de Santa María; y a la hora oportuna canto de la Salve;\\n3° En el último sábado de mes, plegarias especiales por los cristianos oprimidos;\\n4° Celebración solemne de su festividad, el 24 de septiembre;\\n5° Dedicación de las provincias, iglesias y oratorios;\\n6° Presencia de su imagen en los coros y habitaciones.","imagen":"/uploads/landing/devocion-como-honramos-a-la-madre-de-dios-v1.webp"},{"titulo":"Honramos a nuestro Padre","descripcion":"Honramos a nuestro Padre celebrando en cada comunidad solemnemente su fiesta, exponiendo sus virtudes y ejemplos a los fieles, instruyendo a los terciarios, cofrades y otros asociados a nuestra Orden en el conocimiento de su vida y obra; y con el canto de alguna alabanza en su honor después del canto de la Salve sabatina.","imagen":"/uploads/landing/devocion-honramos-a-nuestro-padre-v1.webp"},{"titulo":"Los santos de la Orden","descripcion":"Honramos también a los santos de la Orden imitando sus virtudes, dedicándoles, donde sea conveniente, provincias, casas e iglesias y extendiendo su devoción entre los fieles.","imagen":"/uploads/landing/devocion-los-santos-de-la-orden-v1.webp"}]},"historia":{"titulo":"Nuestra historia","descripcion":"Conoce el origen de la Orden de la Merced y el significado de su escudo.","tarjetas":[{"titulo":"Historia de la Orden Mercedaria","lema":"Libres para liberar","resumen":"Fundada en Barcelona en 1218 por san Pedro Nolasco, la Orden de la Merced nació para rescatar a los cristianos cautivos. Su lema es «Libres para liberar».","detalle":"La Orden de la Bienaventurada Virgen María de la Merced de la Redención de los Cautivos fue fundada el 10 de agosto de 1218 en Barcelona por san Pedro Nolasco, con el apoyo de san Raimundo de Peñafort y del rey Jaime I de Aragón.\\n\\nNació como respuesta a una realidad dolorosa: muchos cristianos eran hechos cautivos y corrían el riesgo de perder su libertad y su fe. Según la tradición, la Virgen María se apareció a san Pedro Nolasco y le inspiró fundar una comunidad dedicada a rescatarlos.\\n\\nAdemás de los votos de obediencia, pobreza y castidad, los mercedarios profesan un cuarto voto: quedar en rehenes, si fuera necesario, en lugar de quienes están en peligro de perder su fe. De ahí nace su lema: «Libres para liberar».\\n\\nCon los siglos, la Orden extendió su misión a otras tierras, entre ellas América, y hoy acompaña a quienes viven nuevas formas de esclavitud, para que recuperen su libertad física, moral y espiritual."},{"titulo":"Significado del escudo mercedario","lema":"","resumen":"El escudo une la cruz de la Catedral de Barcelona y las barras de Aragón, bajo una corona real: la Iglesia y la Corona al servicio de la liberación.","detalle":"El escudo de la Orden de la Merced reúne dos emblemas, coronados por una corona real.\\n\\nLa cruz blanca sobre fondo rojo es la cruz de la Catedral de Barcelona, ciudad donde nació la Orden. Representa a la Iglesia y a Cristo, que entrega su vida para liberar al ser humano.\\n\\nLas cuatro barras rojas sobre fondo dorado son las armas de la Corona de Aragón y recuerdan al rey Jaime I, protector y cofundador de la Orden.\\n\\nLa corona que corona el escudo expresa ese patrocinio real. Así, el escudo muestra la unión de la Iglesia y la Corona en una misma obra: la redención de los cautivos."}]},"fechas":{"titulo":"Fechas importantes","descripcion":"Celebraciones y recuerdos que marcan el camino de la familia mercedaria.","tarjetas":[{"fecha":"7 de enero","titulo":"San Raimundo de Peñafort","descripcion":"Recordamos a san Raimundo de Peñafort, quien colaboró con san Pedro Nolasco en la fundación de la Orden de la Merced.","imagen":"/uploads/landing/fecha-san-raimundo-de-penafort-v1.webp"},{"fecha":"28 de enero","titulo":"San Pedro Nolasco","descripcion":"Fiesta de nuestro Padre y fundador, titular de nuestra parroquia. Se celebra solemnemente, dando a conocer sus virtudes y ejemplos a los fieles.","imagen":"/uploads/landing/fecha-san-pedro-nolasco-v1.webp"},{"fecha":"1 de agosto","titulo":"Aparición de la Virgen de la Merced","descripcion":"Según la tradición, en 1218 la Virgen María se apareció a san Pedro Nolasco y le inspiró fundar una Orden para rescatar a los cautivos.","imagen":"/uploads/landing/fecha-aparicion-de-la-virgen-de-la-merced-v1.webp"},{"fecha":"10 de agosto","titulo":"Fundación de la Orden","descripcion":"En 1218, en Barcelona, san Pedro Nolasco fundó la Orden de la Bienaventurada Virgen María de la Merced de la Redención de los Cautivos.","imagen":"/uploads/landing/fecha-fundacion-de-la-orden-v1.webp"},{"fecha":"31 de agosto","titulo":"San Ramón Nonato","descripcion":"Religioso mercedario que se entregó por la libertad de los cautivos. Es invocado como patrono de las mujeres embarazadas, las parteras y los recién nacidos.","imagen":"/uploads/landing/fecha-san-ramon-nonato-v1.webp"},{"fecha":"24 de septiembre","titulo":"Nuestra Señora de la Merced","descripcion":"Celebración solemne de la festividad de nuestra santísima Madre de la Merced.","imagen":"/uploads/landing/fecha-nuestra-senora-de-la-merced-v1.webp"}]},"imagenes":{"historia_1":"/uploads/landing/historia-1-v1.webp","historia_2":"/uploads/landing/historia-2-v1.webp","historia_3":"/uploads/landing/historia-3-v1.webp"}}'
WHERE NOT EXISTS (SELECT 1 FROM contenido_landing WHERE id = 1);
